/**
 * pin — keep <pin>...</pin> content alive across compaction.
 *
 * How it works:
 *  1. The `session.compact` hook fires whenever the conversation is about to
 *     be compacted (`/compact`, the auto threshold, a plugin, or precompute).
 *     `e.messages` is the full transcript being compacted.
 *  2. We extract every <pin>...</pin> block from that transcript, nudge the
 *     summarizer (via `instructions`) to keep pinned content, then call
 *     `next(e)` to let the engine (and any hooks beneath) actually compact.
 *  3. Whatever comes back, we append one built message carrying every pinned
 *     block *with its <pin> tags intact*. Because the tags survive in that
 *     message, the next compaction re-extracts them — pins are permanent
 *     until the user starts a fresh session or edits them away.
 *
 * Deduplication is by normalized pin text, so re-injection never snowballs.
 */
import type { Register, SessionMessage } from 'claude-code'

const PIN_RE = /<pin>([\s\S]*?)<\/pin>/g
const MARKER = '[pin] Pinned context (preserved across compaction — do not summarize away):'

/** Extract unique, non-empty pinned blocks from a transcript, oldest first. */
const extractPins = (messages: readonly SessionMessage[]): string[] => {
  const seen = new Set<string>()
  const pins: string[] = []
  for (const m of messages) {
    for (const match of m.text.matchAll(PIN_RE)) {
      const body = (match[1] ?? '').trim()
      if (!body) continue
      const key = body.replace(/\s+/g, ' ')
      if (seen.has(key)) continue
      seen.add(key)
      pins.push(body)
    }
  }
  return pins
}

/** Build the carrier message that rides through every future compaction. */
const pinCarrier = (pins: string[]): SessionMessage => ({
  role: 'user',
  text: [MARKER, ...pins.map((p) => `<pin>\n${p}\n</pin>`)].join('\n\n'),
  toolUses: [],
})

export const register: Register = (on) => {
  // Core behavior: wrap compaction, re-append pinned content afterwards.
  on('session.compact', async ($, e, next) => {
    const pins = extractPins(e.messages)
    if (pins.length === 0) return next(e)

    // Belt: tell the summarizer to respect pins.
    const nudge =
      'Preserve verbatim any content wrapped in <pin>...</pin> tags; it is critical context the user explicitly marked.'
    const instructions = e.instructions ? `${e.instructions}\n\n${nudge}` : nudge

    const result = await next({ ...e, instructions })
    if (result.skip !== undefined) return result

    // Suspenders: guarantee survival by appending a carrier message.
    // Drop any previous carrier first so exactly one exists after each pass.
    const kept = result.messages.filter((m) => !m.text.startsWith(MARKER))
    const messages = [...kept, pinCarrier(pins)]

    await $.ui.status(`pin: preserved ${pins.length} pinned block${pins.length === 1 ? '' : 's'} through compaction`)
    $.ui.invalidate('ui.render')
    return { ...result, messages }
  })

  // Optional nicety: a one-line strip above the prompt showing the pin count.
  // Delete this block if your build's AbovePrompt contract differs — the
  // compaction hook above is self-sufficient.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e)
    const count = extractPins(await $.session.messages()).length
    if (count === 0) return below
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        <Text dimColor>{`📌 ${count} pinned block${count === 1 ? '' : 's'} will survive compaction`}</Text>
        {below}
      </Box>
    )
  })
}

